358	    /** Matches a well-formed postcode: exactly 4 digits. */
359	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
360	
361	    /**
362	     * Whether {@code owner}'s postcode is acceptable. Postcode is optional: a null postcode is always
363	     * accepted. When present it must be a 4-digit value and, when the owner's city maps to a known
364	     * region, must fall within that region's inclusive range (NSW 2000-2099, VIC 3000-3099,
365	     * QLD 4000-4099); a city with no known region accepts any 4-digit postcode. The region-to-range
366	     * table lives on {@link Owner#postcodeRangeForRegion(String)} and is shared, not duplicated here.
367	     */
368	    private static boolean isPostcodeValidForCity(Owner owner) {
369	        String postcode = owner.getPostcode();
370	        if (postcode == null) {
371	            return true;
372	        }
373	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
374	            return false;
375	        }
376	        int[] range = Owner.postcodeRangeForRegion(owner.getRegion());
377	        if (range == null) {
378	            return true;
379	        }
380	        int value = Integer.parseInt(postcode);
381	        return value >= range[0] && value <= range[1];
382	    }
383	
384	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
385	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
386	
387	    /**
388	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
389	     * code are kept when present; otherwise country code '+61' is assumed and a single
390	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
391	     * stripped. The result must be a '+' followed by 8 to 15 digits, and its national number
392	     * must have the length required for its country code ('+61' => 9 digits, '+1' => 10).
393	     * Returns {@code null} when the number cannot form a valid E.164 value.
394	     */
395	    private static String normalizeTelephone(String telephone) {
396	        if (telephone == null) {
397	            return null;
398	        }
399	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
400	        String e164;
401	        if (cleaned.startsWith("+")) {
402	            e164 = cleaned;
403	        } else {
404	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
405	            e164 = "+61" + national;
406	        }
407	        if (!E164_PATTERN.matcher(e164).matches()) {
408	            return null;
409	        }
410	        return hasValidNationalNumberLength(e164) ? e164 : null;
411	    }
412	
413	    /**
414	     * Whether the national number of a well-formed E.164 value has the length required for its
415	     * country code. The country-code length table lives on {@link Owner#nationalNumberLength(String)}
416	     * and is shared, not duplicated here; a country code carrying no length rule is accepted.
417	     */
418	    private static boolean hasValidNationalNumberLength(String e164) {
419	        String countryCode = Owner.countryCodeOf(e164);
420	        if (countryCode == null) {
421	            return true;
422	        }
423	        return e164.length() - countryCode.length() == Owner.nationalNumberLength(countryCode);
424	    }
